import{_ as a,o as s,c as i,a2 as t}from"./chunks/framework.BXzK3EA4.js";const k=JSON.parse('{"title":"Day 4: Yocto Releases, BSP Layers & WIC","description":"","frontmatter":{},"headers":[],"relativePath":"day4-yocto-releases-bsp-layers-wic.md","filePath":"day4-yocto-releases-bsp-layers-wic.md"}'),n={name:"day4-yocto-releases-bsp-layers-wic.md"};function o(l,e,r,p,c,d){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="day-4-yocto-releases-bsp-layers-wic" tabindex="-1">Day 4: Yocto Releases, BSP Layers &amp; WIC <a class="header-anchor" href="#day-4-yocto-releases-bsp-layers-wic" aria-label="Permalink to &quot;Day 4: Yocto Releases, BSP Layers &amp; WIC&quot;">​</a></h1><div style="background:linear-gradient(135deg, #11998e 0%, #38ef7d 100%);padding:1.5rem;border-radius:12px;margin-bottom:2rem;color:white;"><p><strong>🎯 Learning Objectives</strong></p><p>By the end of this module, you will be able to:</p><ol><li>Explain the Yocto Project release cycle and select the appropriate LTS branch</li><li>Add a Board Support Package (BSP) layer (<code>meta-ti</code>) to your build environment</li><li>Configure the <code>WIC</code> tool to automatically generate partitioned, bootable disk images</li><li>Explain the anatomy of a Kickstart (<code>.wks</code>) file</li></ol></div><div class="info custom-block"><p class="custom-block-title">PREREQUISITES</p><ul><li>Completed <a href="/day3-beaglebone-black-hardware-bringup.html">Day 3: BeagleBone Black Hardware Bring-Up</a></li><li>Working Poky build environment</li></ul></div><hr><h2 id="_1-yocto-project-release-cycles" tabindex="-1">1. Yocto Project Release Cycles <a class="header-anchor" href="#_1-yocto-project-release-cycles" aria-label="Permalink to &quot;1. Yocto Project Release Cycles&quot;">​</a></h2><p>The Yocto Project follows a strict 6-month release cadence, producing a new major version every April and October. To provide stability for production products, certain releases are designated as <strong>Long Term Support (LTS)</strong> and receive security patches and bug fixes for 4+ years.</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gantt</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    title Yocto Project Recent LTS Releases</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    dateFormat  YYYY-MM</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    axisFormat  %Y</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    section LTS Branches</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Dunfell (3.1)     :active, a1, 2020-04, 2024-04</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Kirkstone (4.0)   :active, a2, 2022-04, 2026-04</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Scarthgap (5.0)   :active, a3, 2024-04, 2028-04</span></span></code></pre></div><h3 id="choosing-the-right-branch" tabindex="-1">Choosing the Right Branch <a class="header-anchor" href="#choosing-the-right-branch" aria-label="Permalink to &quot;Choosing the Right Branch&quot;">​</a></h3><p>When starting a new embedded Linux project, <strong>always choose the most recent LTS release</strong> (e.g., Scarthgap or Kirkstone). Do not use interim releases (like Mickledore or Nanbield) for commercial products, as they lose community support after just 7 months.</p><p><strong>Golden Rule of Yocto Layering:</strong> Every layer you clone (Poky, meta-ti, meta-raspberrypi, meta-xilinx) <strong>must be checked out to the exact same release branch name</strong>. Mixing a &quot;Kirkstone&quot; Poky with a &quot;Scarthgap&quot; BSP layer will cause severe parsing errors.</p><hr><h2 id="_2-integrating-a-board-support-package-bsp-layer" tabindex="-1">2. Integrating a Board Support Package (BSP) Layer <a class="header-anchor" href="#_2-integrating-a-board-support-package-bsp-layer" aria-label="Permalink to &quot;2. Integrating a Board Support Package (BSP) Layer&quot;">​</a></h2><p>While <code>meta-yocto-bsp</code> (included in Poky) provides basic support for reference boards like the BeagleBone Black, silicon vendors maintain their own official BSP layers containing optimized kernels, proprietary graphics drivers, and hardware acceleration libraries.</p><p>For Texas Instruments (TI) processors like the AM335x on the BeagleBone, the official layer is <code>meta-ti</code>.</p><h3 id="step-1-clone-the-bsp-layer" tabindex="-1">Step 1: Clone the BSP Layer <a class="header-anchor" href="#step-1-clone-the-bsp-layer" aria-label="Permalink to &quot;Step 1: Clone the BSP Layer&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/poky</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Remember: The branch must match your Poky branch!</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kirkstone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git://git.yoctoproject.org/meta-ti</span></span></code></pre></div><h3 id="step-2-anatomy-of-a-bsp-layer" tabindex="-1">Step 2: Anatomy of a BSP Layer <a class="header-anchor" href="#step-2-anatomy-of-a-bsp-layer" aria-label="Permalink to &quot;Step 2: Anatomy of a BSP Layer&quot;">​</a></h3><p>Let&#39;s examine the structure of <code>meta-ti</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>meta-ti/</span></span>
<span class="line"><span>├── conf/</span></span>
<span class="line"><span>│   ├── machine/              # Hardware definitions (beaglebone, am335x-evm)</span></span>
<span class="line"><span>│   └── layer.conf            # Layer priority and dependency definitions</span></span>
<span class="line"><span>├── recipes-kernel/</span></span>
<span class="line"><span>│   └── linux/                # TI-optimized linux-ti-staging kernel recipes</span></span>
<span class="line"><span>├── recipes-bsp/</span></span>
<span class="line"><span>│   └── u-boot/               # TI-optimized U-Boot bootloader recipes</span></span>
<span class="line"><span>└── recipes-graphics/         # PowerVR GPU drivers (SGX)</span></span></code></pre></div><h3 id="step-3-add-the-layer-to-your-build" tabindex="-1">Step 3: Add the Layer to Your Build <a class="header-anchor" href="#step-3-add-the-layer-to-your-build" aria-label="Permalink to &quot;Step 3: Add the Layer to Your Build&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake-layers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add-layer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../meta-ti/meta-ti-bsp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake-layers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add-layer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../meta-ti/meta-ti-extras</span></span></code></pre></div><p>Verify it was added successfully:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake-layers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show-layers</span></span></code></pre></div><h3 id="step-4-configure-local-conf" tabindex="-1">Step 4: Configure <code>local.conf</code> <a class="header-anchor" href="#step-4-configure-local-conf" aria-label="Permalink to &quot;Step 4: Configure \`local.conf\`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># In conf/local.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MACHINE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;beaglebone&quot;</span></span></code></pre></div><hr><h2 id="_3-the-wic-tool-automated-disk-image-creation" tabindex="-1">3. The WIC Tool: Automated Disk Image Creation <a class="header-anchor" href="#_3-the-wic-tool-automated-disk-image-creation" aria-label="Permalink to &quot;3. The WIC Tool: Automated Disk Image Creation&quot;">​</a></h2><p>In Day 3, you manually partitioned an SD card using <code>fdisk</code>. In a production environment or CI/CD pipeline, this process must be automated. The <strong>OpenEmbedded Image Creator (WIC)</strong> tool solves this by generating a ready-to-flash disk image containing the partition table, bootloader, kernel, and rootfs.</p><h3 id="_3-1-enabling-wic-in-local-conf" tabindex="-1">3.1 Enabling WIC in <code>local.conf</code> <a class="header-anchor" href="#_3-1-enabling-wic-in-local-conf" aria-label="Permalink to &quot;3.1 Enabling WIC in \`local.conf\`&quot;">​</a></h3><p>To instruct BitBake to produce a <code>.wic</code> file for your image, add <code>wic</code> to the <code>IMAGE_FSTYPES</code> variable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Generate both a tarball and a WIC image</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">IMAGE_FSTYPES</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;tar.bz2 wic&quot;</span></span></code></pre></div><h3 id="_3-2-kickstart-files-wks" tabindex="-1">3.2 Kickstart Files (<code>.wks</code>) <a class="header-anchor" href="#_3-2-kickstart-files-wks" aria-label="Permalink to &quot;3.2 Kickstart Files (\`.wks\`)&quot;">​</a></h3><p>WIC relies on Kickstart (<code>.wks</code>) files to define the partition layout. BSP layers usually provide default <code>.wks</code> files. For the BeagleBone, it looks like this:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># am335x-sdimage.wks</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># Create a boot partition formatted as FAT32, copy boot files into it</span></span>
<span class="line"><span>part /boot --source bootimg-partition --ondisk mmcblk0 --fstype=vfat --label boot --active --align 4 --size 16</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Create the rootfs partition formatted as EXT4, copy root filesystem into it</span></span>
<span class="line"><span>part / --source rootfs --ondisk mmcblk0 --fstype=ext4 --label root --align 4</span></span></code></pre></div><h3 id="_3-3-flashing-a-wic-image" tabindex="-1">3.3 Flashing a WIC Image <a class="header-anchor" href="#_3-3-flashing-a-wic-image" aria-label="Permalink to &quot;3.3 Flashing a WIC Image&quot;">​</a></h3><p>When you run <code>bitbake core-image-minimal</code>, WIC parses the <code>.wks</code> file and generates <code>core-image-minimal-beaglebone.wic</code>.</p><p>Flash it to your SD card (replace <code>/dev/sdX</code> with your actual SD card device, e.g., <code>/dev/sdb</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># WARNING: This will destroy all data on /dev/sdX</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> if=tmp/deploy/images/beaglebone/core-image-minimal-beaglebone.wic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> of=/dev/sdX</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bs=4M</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status=progress</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sync</span></span></code></pre></div><hr><h2 id="_4-hands-on-lab-exercises" tabindex="-1">4. Hands-On Lab Exercises <a class="header-anchor" href="#_4-hands-on-lab-exercises" aria-label="Permalink to &quot;4. Hands-On Lab Exercises&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">LAB 4.1: Exploring Layer Priorities</p><ol><li>Run <code>bitbake-layers show-layers</code>. Look at the &quot;Priority&quot; column.</li><li>Open <code>meta-ti/meta-ti-bsp/conf/layer.conf</code> and find the <code>BBFILE_PRIORITY_meta-ti-bsp</code> variable.</li><li>If two layers provide a recipe for <code>u-boot</code>, the one with the higher priority number &quot;wins&quot;. Which layer has higher priority: <code>meta-yocto-bsp</code> or <code>meta-ti-bsp</code>?</li></ol></div><div class="tip custom-block"><p class="custom-block-title">LAB 4.2: Inspecting WIC Images (QEMU/Host)</p><p>You can inspect the contents of a generated <code>.wic</code> file without flashing it:</p><ol><li>Locate the <code>.wic</code> file in <code>tmp/deploy/images/&lt;machine&gt;/</code></li><li>Run <code>fdisk -l *.wic</code> to see the partition table inside the image file.</li><li>Observe how the FAT32 boot partition and ext4 rootfs partition match the rules defined in the <code>.wks</code> file.</li></ol></div><hr><h2 id="_5-further-reading" tabindex="-1">5. Further Reading <a class="header-anchor" href="#_5-further-reading" aria-label="Permalink to &quot;5. Further Reading&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>URL</th></tr></thead><tbody><tr><td>Yocto Project Releases</td><td><a href="https://wiki.yoctoproject.org/wiki/Releases" target="_blank" rel="noreferrer">wiki.yoctoproject.org/wiki/Releases</a></td></tr><tr><td>WIC Documentation</td><td><a href="https://docs.yoctoproject.org/dev-manual/wic.html" target="_blank" rel="noreferrer">docs.yoctoproject.org/dev-manual/wic.html</a></td></tr><tr><td>OpenEmbedded Layer Index</td><td><a href="https://layers.openembedded.org/" target="_blank" rel="noreferrer">layers.openembedded.org</a></td></tr></tbody></table><hr><div style="display:flex;justify-content:space-between;margin-top:2rem;padding-top:1rem;border-top:1px solid #e2e8f0;"><a href="/day3-beaglebone-black-hardware-bringup">← Day 3: BeagleBone Black Bring-Up</a><a href="/day5-raspberry-pi-hardware-bringup">Day 5: Raspberry Pi Bring-Up →</a></div>`,47)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
